-- 054. Шеф: без сокращений в речи (25.11, на слух: «Медеуский РОВД» читается плохо).
-- Речь: «Медеуский РОВД» → «Районный отдел», «РОВД закрыть» → «Район закрыть», «высшей школы МВД» → «милицейской академии».
-- Строка рассказчика «Так решил Медеуский РОВД» не озвучивается и остаётся.
begin;
update cases set intro_text = replace(replace(replace(intro_text, 'Медеуский РОВД нам подарок прислал.', 'Районный отдел нам подарок прислал.'), 'РОВД закрыть хочет.', 'Район закрыть хочет.'), 'доцент из высшей школы МВД', 'доцент из милицейской академии') where id = '029e23c3-01e0-5d19-a0e7-3e0c2446ebab';
update characters set intro_text = replace(replace(replace(intro_text, 'Медеуский РОВД нам подарок прислал.', 'Районный отдел нам подарок прислал.'), 'РОВД закрыть хочет.', 'Район закрыть хочет.'), 'доцент из высшей школы МВД', 'доцент из милицейской академии') where id = '57949d2d-0b2d-5c04-812c-5849e9441857';
update phone_calls set dialogue_text = replace(dialogue_text, 'Звонил начальник Медеуского РОВД.', 'Звонил начальник районного отдела.') where id = '6879697e-dfaf-523c-8a4f-a809dea63c0a';
commit;
select position('Районный отдел нам' in intro_text) > 0 as briefing_ok from characters where id = '57949d2d-0b2d-5c04-812c-5849e9441857';
